openai_client.py

A minimal, standard-library-only client for OpenAI's Responses API.

Features
- Uses only Python's standard library (urllib, json, time, os, argparse).
- Reads API key from "'`OPENAI_API_KEY`; supports `OPENAI_ORG` and `OPENAI_PROJECT`.
- Simple `send` method for text prompts to `/v1/responses`.
- Careful about privacy: avoids logging prompts or API keys.
- Small retry/backoff on 429/5xx.
- Can be used as a module or a CLI (`python openai_client.py "your prompt"`).

Note: This targets the Responses API (`/v1/responses`).
Docs: https://platform.openai.com/docs/guides/responses
"""
from __future__ import annotations

import argparse
import json
import os
import sys
import time
import typing as _t
from urllib import request, error


_DEFAULT_MODEL = os.environ.get("OPENAI_MODEL", "gpt-4.1-mini")
_DEFAULT_BASE_URL = os.environ.get("OPENAI_BASE_URL", "https://api.openai.com")
_RESPONSES_PATH = "/v1/responses"


class OpenAIError(Exception):
    """Base exception for OpenAI client errors."""


class OpenAIAuthError(OpenAIError):
    """Raised when authentication fails or API key is missing."""


class OpenAIRateLimitError(OpenAIError):
    """Raised when the API returns HTTP 429."""


class OpenAIAPIError(OpenAIError):
    """Raised for other non-success HTTP responses."""


class OpenAIClient:
    """Tiny client for OpenAI Responses API using only the stdlib.

    Parameters
    - api_key: API key string. If None, uses `OPENAI_API_KEY` env var.
    - base_url: API base URL. Defaults to `https://api.openai.com`.
    - organization: Optional organization ID for the `OpenAI-Organization` header.
    - project: Optional project ID for the `OpenAI-Project` header.
    - timeout: Default request timeout (seconds).
    - max_retries: Retries for 429/5xx.
    - backoff_factor: Exponential backoff base delay (seconds).
    """

    def __init__(
        self,
        api_key: str | None = None,
        *,
        base_url: str = _DEFAULT_BASE_URL,
        organization: str | None = os.environ.get("OPENAI_ORG"),
        project: str | None = os.environ.get("OPENAI_PROJECT"),
        timeout: float = 60.0,
        max_retries: int = 3,
        backoff_factor: float = 0.5,
        user_agent: str | None = None,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise OpenAIAuthError(
                "Missing API key. Set OPENAI_API_KEY or pass api_key explicitly."
            )
        self.base_url = base_url.rstrip("/")
        self.organization = organization
        self.project = project
        self.timeout = float(timeout)
        self.max_retries = max(0, int(max_retries))
        self.backoff_factor = float(backoff_factor)
        self.user_agent = user_agent or "openai-client-stdlib/1.0"

    # ----------------------------- Public API ------------------------------ #
    def send(
        self,
        prompt: str,
        *,
        model: str = _DEFAULT_MODEL,
        system: str | None = None,
        temperature: float | None = None,
        top_p: float | None = None,
        extra_body: dict[str, _t.Any] | None = None,
        timeout: float | None = None,
    ) -> dict[str, _t.Any]:
        """Send a text `prompt` to the Responses API and return parsed JSON.

        Returns the full JSON response as a dict. Convenience fields you may
        want:
          - response["output_text"]: when available, the assistant text.
          - response["output"]: canonical list of output items.

        This method intentionally avoids logging the prompt.
        """
        body: dict[str, _t.Any] = {"model": model}

        # When only a simple user prompt is needed, `input` can be a string.
        # If a `system` instruction is also provided, we structure input as a
        # pair of message-like content blocks to preserve roles.
        if system:
            body["input"] = [
                {
                    "role": "system",
                    "content": [
                        {"type": "input_text", "text": str(system)}
                    ],
                },
                {
                    "role": "user",
                    "content": [
                        {"type": "input_text", "text": str(prompt)}
                    ],
                },
            ]
        else:
            body["input"] = str(prompt)

        if temperature is not None:
            body["temperature"] = float(temperature)
        if top_p is not None:
            body["top_p"] = float(top_p)
        if extra_body:
            # Shallow merge; explicit arguments win on conflict.
            for k, v in extra_body.items():
                if k not in body:
                    body[k] = v

        return self._request_json("POST", _RESPONSES_PATH, body, timeout=timeout)

    def ask_text(
        self,
        prompt: str,
        *,
        model: str = _DEFAULT_MODEL,
        system: str | None = None,
        temperature: float | None = None,
        top_p: float | None = None,
        extra_body: dict[str, _t.Any] | None = None,
        timeout: float | None = None,
    ) -> str:
        """Send a prompt and return best-effort plain text from the response."""
        data = self.send(
            prompt,
            model=model,
            system=system,
            temperature=temperature,
            top_p=top_p,
            extra_body=extra_body,
            timeout=timeout,
        )
        text = self._extract_output_text(data)
        if text is not None:
            return text
        # Fallback: compact the content parts into a text blob.
        return self._fallback_text_from_output(data)

    # --------------------------- Internal helpers -------------------------- #
    def _headers(self) -> dict[str, str]:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "User-Agent": self.user_agent,
        }
        if self.organization:
            headers["OpenAI-Organization"] = self.organization
        if self.project:
            headers["OpenAI-Project"] = self.project
        return headers

    def _request_json(
        self,
        method: str,
        path: str,
        body: dict[str, _t.Any] | None = None,
        *,
        timeout: float | None = None,
    ) -> dict[str, _t.Any]:
        url = f"{self.base_url}{path}"
        payload = None
        if body is not None:
            payload = json.dumps(body).encode("utf-8")
        req = request.Request(url=url, data=payload, method=method.upper())
        for k, v in self._headers().items():
            req.add_header(k, v)

        attempt = 0
        last_exc: Exception | None = None
        deadline = time.time() + (timeout if timeout is not None else self.timeout)

        while True:
            attempt += 1
            try:
                rem_timeout = max(0.1, deadline - time.time())
                with request.urlopen(req, timeout=rem_timeout) as resp:
                    status = resp.getcode()
                    raw = resp.read()
                    # Expect 2xx
                    if 200 <= status < 300:
                        if not raw:
                            return {}
                        try:
                            return json.loads(raw.decode("utf-8"))
                        except json.JSONDecodeError as je:
                            raise OpenAIAPIError(
                                f"Invalid JSON in response (HTTP {status})."
                            ) from je
                    # Non-2xx fallthrough handled below.
                    err_text = raw.decode("utf-8", errors="replace") if raw else ""
                    self._raise_for_status(status, err_text)

            except error.HTTPError as he:  # Non-2xx with body
                status = he.code
                try:
                    err_text = he.read().decode("utf-8", errors="replace")
                except Exception:
                    err_text = ""
                # Retry on 429/5xx
                if self._should_retry(status):
                    if attempt <= self.max_retries and time.time() < deadline:
                        self._sleep_backoff(attempt)
                        continue
                self._raise_for_status(status, err_text)
            except error.URLError as ue:
                last_exc = ue
                if attempt <= self.max_retries and time.time() < deadline:
                    self._sleep_backoff(attempt)
                    continue
                raise OpenAIAPIError("Network error talking to OpenAI API") from ue
            except Exception as ex:
                last_exc = ex
                if attempt <= self.max_retries and time.time() < deadline:
                    self._sleep_backoff(attempt)
                    continue
                raise

            # If we got here due to a logic path, bubble last exception if any.
            if last_exc is not None:
                raise last_exc

    @staticmethod
    def _should_retry(status: int) -> bool:
        return status == 429 or 500 <= status < 600

    def _sleep_backoff(self, attempt: int) -> None:
        delay = self.backoff_factor * (2 ** (attempt - 1))
        time.sleep(min(delay, 5.0))

    @staticmethod
    def _raise_for_status(status: int, body_text: str | None) -> None:
        # Try to preserve privacy: do not echo user prompts; show succinct error.
        # Parse JSON error if present.
        msg = f"OpenAI API error (HTTP {status})"
        detail = None
        if body_text:
            try:
                data = json.loads(body_text)
                # Common error shapes: {"error": {"message": "...", "type": "..."}}
                err = data.get("error") if isinstance(data, dict) else None
                if isinstance(err, dict) and "message" in err:
                    detail = str(err.get("message"))
                elif isinstance(data, dict) and "message" in data:
                    detail = str(data.get("message"))
            except Exception:
                # Keep body quiet to avoid leaking content.
                pass
        if detail:
            msg = f"{msg}: {detail}"

        if status == 401 or status == 403:
            raise OpenAIAuthError(msg)
        if status == 429:
            raise OpenAIRateLimitError(msg)
        raise OpenAIAPIError(msg)

    @staticmethod
    def _extract_output_text(resp: dict[str, _t.Any]) -> str | None:
        # Prefer the convenience field if the API includes it.
        text = resp.get("output_text") if isinstance(resp, dict) else None
        if isinstance(text, str):
            return text
        # Some SDKs expose `response` or `content[0].text`—try a few shapes.
        if isinstance(resp, dict):
            r = resp.get("response")
            if isinstance(r, str):
                return r
        return None

    @staticmethod
    def _fallback_text_from_output(resp: dict[str, _t.Any]) -> str:
        # Compact any recognized text parts from canonical `output` items.
        parts: list[str] = []
        output = resp.get("output") if isinstance(resp, dict) else None
        if isinstance(output, list):
            for item in output:
                if not isinstance(item, dict):
                    continue
                content = item.get("content")
                if isinstance(content, list):
                    for c in content:
                        if not isinstance(c, dict):
                            continue
                        # Common fields: {type: "output_text"|"text", text: "..."}
                        t = c.get("text") if isinstance(c.get("text"), str) else None
                        if isinstance(t, str):
                            parts.append(t)
        return "".join(parts).strip()


# ------------------------------- CLI support ------------------------------- #

def _cli(argv: list[str]) -> int:
    p = argparse.ArgumentParser(
        description=(
            "Send a private text prompt to OpenAI'"'s Responses API using only the stdlib.\"
        )
    )
    p.add_argument(\"prompt\", nargs=\"?\", help=\"Prompt text. If omitted, reads stdin.\")
    p.add_argument(
        \"-m\",
        \"--model\",
        default=_DEFAULT_MODEL,
        help=f\"Model ID (default: {_DEFAULT_MODEL})\",
    )
    p.add_argument(\"--system\", help=\"Optional system instruction.\")
    p.add_argument(\"--temperature\", type=float, help=\"Sampling temperature.\")
    p.add_argument(\"--top-p\", dest=\"top_p\", type=float, help=\"Nucleus sampling p.\")
    p.add_argument(
        \"--json\",
        action=\"store_true\",
        help=\"Print raw JSON response instead of text only.\",
    )
    p.add_argument(
        \"--timeout\",
        type=float,
        default=float(os.environ.get(\"OPENAI_TIMEOUT\", 60)),
        help=\"Request timeout in seconds (default 60 or "'$OPENAI_TIMEOUT).",
    )

    args = p.parse_args(argv)

    prompt = args.prompt
    if prompt is None:
        # Read entire stdin as the prompt (no echo).
        prompt = sys.stdin.read()

    try:
        client = OpenAIClient(timeout=args.timeout)
        if args.json:
            data = client.send(
                prompt,
                model=args.model,
                system=args.system,
                temperature=args.temperature,
                top_p=args.top_p,
            )
            sys.stdout.write(json.dumps(data, ensure_ascii=False, indent=2))
            sys.stdout.write("'"\\n\")
        else:
            text = client.ask_text(
                prompt,
                model=args.model,
                system=args.system,
                temperature=args.temperature,
                top_p=args.top_p,
            )
            sys.stdout.write(text + (\"\\n\" if not text.endswith(\"\\n\") else \"\"))
        return 0
    except OpenAIAuthError as ae:
        sys.stderr.write(f\"Auth error: {ae}\\n\")
        return 2
    except OpenAIRateLimitError as re:
        sys.stderr.write(f\"Rate limit: {re}\\n\")
        return 3
    except OpenAIAPIError as api_err:
        sys.stderr.write(f\"API error: {api_err}\\n\")
        return 4
    except KeyboardInterrupt:
        return 130


if __name__ == \"__main__\":
    raise SystemExit(_cli(sys.argv[1:]))
PY
\"}"

