def _cli(argv: list[str]) -> int:
    p = argparse.ArgumentParser(
        description=(
            "Send a private text prompt to OpenAI'"\\'s Responses API using only the stdlib.\"
        )
    )
    p.add_argument(\"prompt\", nargs=\"?\", help=\"Prompt text. If omitted, reads stdin.\")
    p.add_argument(
        \"-m\",
        \"--model\",
        default=_DEFAULT_MODEL,
        help=f\"Model ID (default: {_DEFAULT_MODEL})\",
    )
    p.add_argument(\"--system\", help=\"Optional system instruction.\")
    p.add_argument(\"--temperature\", type=float, help=\"Sampling temperature.\")
    p.add_argument(\"--top-p\", dest=\"top_p\", type=float, help=\"Nucleus sampling p.\")
    p.add_argument(
        \"--json\",
        action=\"store_true\",
        help=\"Print raw JSON response instead of text only.\",
    )
    p.add_argument(
        \"--timeout\",
        type=float,
        default=float(os.environ.get(\"OPENAI_TIMEOUT\", 60)),
        help=\"Request timeout in seconds (default 60 or "'$OPENAI_TIMEOUT).",
    )

    args = p.parse_args(argv)

    prompt = args.prompt
    if prompt is None:
        # Read entire stdin as the prompt (no echo).
        prompt = sys.stdin.read()

    try:
        client = OpenAIClient(timeout=args.timeout)
        if args.json:
            data = client.send(
                prompt,
                model=args.model,
                system=args.system,
                temperature=args.temperature,
                top_p=args.top_p,
            )
            sys.stdout.write(json.dumps(data, ensure_ascii=False, indent=2))
            sys.stdout.write(chr(10))
        else:
            text = client.ask_text(
                prompt,
                model=args.model,
                system=args.system,
                temperature=args.temperature,
                top_p=args.top_p,
            )
            sys.stdout.write(text + (chr(10) if not text.endswith(chr(10)) else ""))
        return 0
    except OpenAIAuthError as ae:
        sys.stderr.write(f"Auth error: {ae}" + chr(10))
        return 2
    except OpenAIRateLimitError as re:
        sys.stderr.write(f"Rate limit: {re}" + chr(10))
        return 3
    except OpenAIAPIError as api_err:
        sys.stderr.write(f"API error: {api_err}" + chr(10))
        return 4
    except KeyboardInterrupt:
        return 130


if __name__ == "__main__":
    raise SystemExit(_cli(sys.argv[1:]))
